Translate("deDE", "darkshore", {
	title = "Dunkelküste",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Dunkelküste ist ein langer, grauer Küstenstrich im Nordwesten von {link:kalimdor}Kalimdor{/link}, jenseits einer schmalen Meerenge gegenüber dem großen Baum {link:teldrassil}Teldrassil{/link}. Ihre Wälder sind selbst zur Mittagszeit düster, ihre Strände sind kalt, und ihre Hügel sind voller Ruinen, die älter sind als jedes Königreich der {link:humans}Menschen{/link}. Die {link:night-elves}Nachtelfen{/link} halten sie von der kleinen Hafenstadt {link:auberdine}Auberdine{/link} aus. Sie haben sie zu einem Tor zwischen ihrer neuen Heimat und der weiten Welt gemacht. Doch das Land, das sie bewachen, ist krank. Seine Flüsse sind verdorben, seine Tiere sind wahnsinnig geworden, und alte Feinde sind in die Ruinen der eigenen Vergangenheit der Elfen zurückgekehrt.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Lange vor der {link:great-sundering}Großen Teilung{/link} blickten diese Hügel auf die Ufer des {link:well-of-eternity}Brunnens der Ewigkeit{/link} hinab. Hier errichtete {link:queen-azshara}Königin Azshara{/link} die Zwillingsstädte {link:ameth-aran}Ameth'Aran{/link} und {link:bashal-aran}Bashal'Aran{/link} für ihre bevorzugten Hochgeborenen und setzte den Fürsten {link:athrikus-narassin}Athrikus Narassin{/link} ein, der sie von seinem {link:tower-of-althalaxx}Turm von Althalaxx{/link} aus regieren sollte. Als der {link:war-of-the-ancients}Krieg der Ahnen{/link} endete und der Brunnen zerstört wurde, fielen die Städte, und das Land wurde zerrissen. Was blieb, wurde zur Küste des neuen Meeres. {link:ruins-of-mathystra}Die Ruinen von Mathystra{/link}, einst ein großes {link:the-bulwark}Bollwerk{/link} der Elfen, zerfielen im Norden. Nach der {link:battle-of-mount-hyjal}Schlacht um den Berg Hyjal{/link} ließen die {link:night-elves}Nachtelfen{/link} {link:teldrassil}Teldrassil{/link} vor dieser Küste emporwachsen. Keine Chronik verzeichnet das Jahr, in dem {link:auberdine}Auberdine{/link} erbaut wurde.]=],
		},
		{
			title = "Die Gegenwart",
			text = [=[{link:auberdine}Auberdine{/link} ist eine bescheidene Stadt, aber sie ist geschäftig. Schiffe bringen Reisende nach {link:teldrassil}Teldrassil{/link} und über das Meer in die Lande der {link:humans}Menschen{/link}. Ein neues Schiff verbindet sie nun mit dem {link:stormwind-harbor}Hafen von Stormwind{/link}, und ein weiteres segelt über {link:southshore}Southshore{/link} zum {link:menethil-harbor}Hafen von Menethil{/link}. Die Stadt braucht jeden Freund, den diese Schiffe bringen können. Die {link:furbolgs}Furbolgs{/link} der {link:blackwood-furbolgs}Schwarzfelle{/link} haben sich gegen die Elfen gewandt. Eine Krankheit breitet sich unter den Distelbären und dem Rotwild aus, und sie scheint aus dem {link:felwood}Teufelswald{/link} im Osten zu fließen. {link:naga}Naga{/link} halten die Ruinen von {link:ruins-of-mathystra}Mathystra{/link}. Der {link:twilight-s-hammer}Schattenhammer{/link} gräbt an der {link:the-master-s-glaive}Meistergleve{/link}, und ein Kult von Hexenmeistern versammelt sich am {link:tower-of-althalaxx}Turm von Althalaxx{/link}. Als der Älteste von Auberdine {link:stormwind-city}Stormwind{/link} um Hilfe bat, hatte Stormwind keine zu geben. {link:darnassus}Darnassus{/link} hat kaum mehr geschickt.]=],
		},
		{
			title = "Bewohner",
			text = [=[• {b}Die {link:night-elves}Nachtelfen{/link} von {link:auberdine}Auberdine{/link}.{/b} {link:sentinels}Schildwachen{/link}, Druiden und Gelehrte, die die Stadt halten und die Verderbnis erforschen, die sie umgibt.
• {b}Die {link:dwarves}Zwerge{/link}.{/b} Bergleute, Schmiede und Händler aus {link:ironforge}Ironforge{/link} sowie die Gelehrten der {link:explorers-league}Forscherliga{/link}, die im Süden graben.
• {b}Die {link:blackwood-furbolgs}Furbolgs der Schwarzfelle{/link}.{/b} Einst Freunde der Elfen, nun wahnsinnig und feindselig in ihren {link:camping}Lagern{/link}.
• {b}Die {link:naga}Naga{/link}.{/b} Die Naga der Stormscale suchen {link:ruins-of-mathystra}Mathystra{/link} und die Höhle hinter den {link:cliffspring-falls}Cliffspring Falls{/link} heim.
• {b}Die {link:murlocs}Murlocs{/link} der Greymist.{/b} Sie drängen sich an der Küste und machen Jagd auf Schiffe und Fischer.
• {b}Die ruhelosen Toten.{/b} Die Geister der Hochgeborenen wandeln noch immer durch die Ruinen von {link:ameth-aran}Ameth'Aran{/link}.
• {b}Die Mondkin.{/b} Sie durchstreifen die östlichen Hügel und werden mit jeder Jahreszeit feindseliger.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Die Zwillingsstädte.{/b} Im Zeitalter Azsharas blühten {link:ameth-aran}Ameth'Aran{/link} und {link:bashal-aran}Bashal'Aran{/link} am {link:well-of-eternity}Brunnen der Ewigkeit{/link}, während die Welt unter ihnen dem Wahnsinn entgegenglitt.
• {b}Die Teilung.{/b} Im Chaos des Krieges versprach {link:athrikus-narassin}Athrikus Narassin{/link} den Bewohnern von Ameth'Aran durch seine Magie ewiges Leben. Ihre Geister haben nie Ruhe gefunden.
• {b}Der lange Schlaf.{/b} Viele Druiden folgten {link:malfurion-stormrage}Malfurion Stormrage{/link} in den Schlaf des {link:emerald-dream}Smaragdgrünen Traums{/link}. Einige der Schlafenden sind kürzlich erwacht und finden ihre alten Heimstätten in Trümmern.
• {b}Die neue Heimat.{/b} Nach dem Krieg gegen die {link:burning-legion}Brennende Legion{/link} machten die {link:night-elves}Nachtelfen{/link} {link:teldrassil}Teldrassil{/link} zu ihrer Heimat, und {link:auberdine}Auberdine{/link} wurde ihr Tor zur Welt.]=],
		},
		{
			title = "Überlieferungen der Küste",
			text = [=[• Große Meereskreaturen stranden in wachsender Zahl an den Stränden der Dunkelküste. Die Priesterinnen des Tempels des Mondes haben erfahren, dass die {link:naga}Naga{/link} sie vertreiben.
• In den östlichen Hügeln steht ein roter Kristall. In ihm liegen Knochenbruchstücke und die Hälfte eines Kieferknochens. Die Mondkin versammeln sich um ihn, und niemand weiß, warum.
• Die Fischer von {link:auberdine}Auberdine{/link} fahren nicht mehr mit ihren Booten hinaus. Sie sagen, die {link:murlocs}Murlocs{/link} hätten alle Zackenbarsche gefressen.]=],
		},
	},
})

Translate("deDE", "auberdine", {
	title = "Auberdine",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Auberdine ist die Hafenstadt der {link:darkshore}Dunkelküste{/link}, an der Küste gegenüber von {link:teldrassil}Teldrassil{/link} erbaut. Ihr Ältester, {link:thundris-windweaver}Thundris Windweaver{/link}, und ihr Dorfrat regieren sie. {link:sentinels}Schildwachen{/link} bewachen sie, und ein Mondbrunnen in ihrem Herzen spendet das reine Wasser, das ihre Druiden und Priesterinnen brauchen. {link:night-elves}Nachtelfen{/link} und {link:dwarves}Zwerge{/link} teilen sich ihr Gasthaus, ihre Schmieden und ihre Docks. Von ihren Stegen fährt ein Schiff hinüber nach {link:rut-theran-village}Rut'theran{/link} am Fuß von Teldrassil, und ein weiteres segelt zum Hafen von Menethil. Nun sind zwei neue Routen hinzugekommen: eine zum {link:stormwind-harbor}Hafen von Stormwind{/link} und eine nach Menethil über {link:southshore}Southshore{/link} im {link:hillsbrad-foothills}Vorgebirge von Hillsbrad{/link}. Die Stadt hofft, dass die Schiffe Hilfe bringen. Bisher haben sie nur Reisende gebracht.]=],
		},
	},
})

Translate("deDE", "ruins-of-mathystra", {
	title = "Die Ruinen von Mathystra",
	aliases = { "Mathystra" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Ruinen von Mathystra liegen im äußersten Nordosten der {link:darkshore}Dunkelküste{/link}. Mathystra war einst ein großes {link:the-bulwark}Bollwerk{/link} der Elfen, und Bruchstücke seiner Magie liegen noch zwischen Gras und zerbrochenen Steinen. Die {link:naga}Naga{/link} der Stormscale halten es nun, und sie plündern den Ort, den ihre eigenen Vorfahren einst Heimat nannten. Ihre Bestienherrinnen beugen die großen Tiere des Meeres ihrem Willen. In letzter Zeit wurde unter den Ruinen etwas Älteres gefunden. Ein elementarer {link:the-night-watch}Wächter{/link} wachte über eine Treppe, die in die Dunkelheit hinabführt, und selbst die Uralten wissen noch nicht, was darunter liegt.]=],
		},
	},
})

Translate("deDE", "bashal-aran", {
	title = "Bashal'Aran",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Bashal'Aran war eine der Zwillingsstädte, die {link:queen-azshara}Königin Azshara{/link} für ihre Hochgeborenen errichtete. Seine Ruinen liegen östlich von {link:auberdine}Auberdine{/link}. Dämonische Irrwische, Grells und {link:satyrs}Satyrn{/link} der Deth'ryll haben sie zu ihrem Unterschlupf gemacht, und sie werden stärker, indem sie sich von der Magie nähren, die noch an den Steinen haftet. Doch es gibt einen Schrein auf einer Klippe im Westen der Ruinen, dem sie sich nicht nähern. Ein blaues Licht hängt um ihn. In ihm wartet der Geist von {link:asterion}Asterion{/link}, dort gebunden von seinem eigenen Meister, länger als irgendein lebender Elf sich erinnern kann.]=],
		},
	},
})

Translate("deDE", "ameth-aran", {
	title = "Ameth'Aran",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Ameth'Aran war der Zwilling von {link:bashal-aran}Bashal'Aran{/link}, eine Stadt der Hochgeborenen am {link:well-of-eternity}Brunnen der Ewigkeit{/link}. Sie wurde in dem Krieg zerstört, der die Welt zerriss. Ihre Bewohner starben nicht wirklich. Sie klammerten sich an das Versprechen von {link:athrikus-narassin}Athrikus Narassin{/link}, und nun wandeln sie als verfluchte, klagende Geister durch die Ruinen und tragen noch immer die magischen Werkzeuge ihrer alten Kunst. Zwei große Tafeln zwischen den Steinen erzählen die Geschichte der Stadt und ihres Falls. Eine uralte blaue Flamme brennt hier noch. Sie ist heiß genug, um Dinge zu zerstören, denen kein anderes Feuer etwas anhaben kann.]=],
		},
	},
})

Translate("deDE", "tower-of-althalaxx", {
	title = "Turm von Althalaxx",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Turm von Althalaxx erhebt sich im Nordosten der {link:darkshore}Dunkelküste{/link}. Er war der Sitz von {link:athrikus-narassin}Athrikus Narassin{/link}, dem Fürsten der Hochgeborenen, der {link:ameth-aran}Ameth'Aran{/link} und {link:bashal-aran}Bashal'Aran{/link} für {link:queen-azshara}Königin Azshara{/link} regierte und die meisten seiner Tage fern von ihnen hier verbrachte. Nach zehntausend Jahren hat der Turm wieder einen Herrn. Eine Schar von Hexenmeistern, die sich {link:cult-of-the-dark-strand}Kult des Dunklen Strangs{/link} nennt, hat ihn eingenommen, und die Stärksten von ihnen halten sich in den oberen Räumen auf. Ein Späher aus {link:auberdine}Auberdine{/link}, {link:balthule-shadowstrike}Balthule Shadowstrike{/link}, hat sein Lager in der Nähe. Er hat Lichtblitze von der Spitze des Turms gesehen und Schreie gehört.]=],
		},
	},
})

Translate("deDE", "grove-of-the-ancients", {
	title = "Der Hain der Uralten",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Hain der Uralten liegt im Süden der {link:darkshore}Dunkelküste{/link}, geschützt von den Bergen. Hier leben die Uralten, große Geister des Waldes, die seit den ältesten Tagen an der Seite der {link:night-elves}Nachtelfen{/link} stehen. {link:onu}Onu{/link}, ein Uralter des Wissens, sammelt Kunde über jede Bedrohung im Land, und die Druiden von {link:auberdine}Auberdine{/link} beherzigen seine Warnungen. Neben ihm steht {link:arbal}Arbal{/link}, ein Uralter des Krieges. Der Hain ist geduldig, wie alle Uralten es sind, doch er ist nicht untätig. Von hier aus wird der Kampf gegen die {link:naga}Naga{/link} und den {link:twilight-s-hammer}Schattenhammer{/link} im Stillen geplant.]=],
		},
	},
})

Translate("deDE", "twilight-vale", {
	title = "Das Zwielichttal",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Zwielichttal ist der Name der südlichen Wälder der {link:darkshore}Dunkelküste{/link}, von den Ruinen von {link:ameth-aran}Ameth'Aran{/link} bis hinab an die Grenzen des {link:ashenvale}Eschentals{/link}. Seine Straßen verbinden {link:auberdine}Auberdine{/link} mit {link:maestra-s-post}Maestras Posten{/link} und {link:astranaar}Astranaar{/link}, und Boten, die sie entlangziehen, tun es auf eigene Gefahr. {link:blackwood-furbolgs}Furbolgs der Schwarzfelle{/link} überfallen Reisende, Mondpirscher schleichen zwischen den Bäumen, und die kranken Bären des Waldes greifen jeden an, der ihnen nahe kommt. {link:grove-of-the-ancients}Der Hain der Uralten{/link}, die {link:the-master-s-glaive}Meistergleve{/link} und die Ausgrabung der {link:explorers-league}Forscherliga{/link} liegen alle im Tal. Wer es durchreist, bleibt auf der Straße.]=],
		},
	},
})

Translate("deDE", "mist-s-edge", {
	title = "Nebelrand",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Nebelrand ist das lange graue Wasser entlang der Küste der {link:darkshore}Dunkelküste{/link}, wo der {link:cliffspring-river}Cliffspring{/link} ins Meer mündet. Seine Strände sind übersät mit den Kadavern großer Meereskreaturen und mit den Trümmern von Schiffen. Zwei dieser Schiffe, die Silberdämmerung und der Nebelschleier, liegen nördlich von {link:auberdine}Auberdine{/link} auf dem Grund, versenkt von {link:murlocs}Murlocs{/link}, als sie in den Hafen einliefen. Krebse huschen über jeden Streifen Sand. Die Murlocs der Greymist errichten ihre Hütten entlang des Ufers, und ihre Häuptlinge jagen Fischer und {link:sentinels}Schildwachen{/link} gleichermaßen.]=],
		},
	},
})

Translate("deDE", "cliffspring-river", {
	title = "Cliffspring",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Cliffspring kommt aus den östlichen Bergen herab und fließt nördlich von {link:auberdine}Auberdine{/link} ins Meer. Eine Brücke überspannt ihn oberhalb seines ersten Wasserfalls. Sein Wasser war einst klar. Nun wird es faulig, und der Älteste von Auberdine fürchtet, dass die Verseuchung die Stadt selbst erreichen wird. Die nördlichen Lager der {link:blackwood-furbolgs}Furbolgs der Schwarzfelle{/link} stehen an seinen Ufern, und ihre Feuer brennen am Wasser. {link:thundris-windweaver}Thundris Windweaver{/link} glaubt, dass die {link:furbolgs}Furbolgs{/link} den Fluss verschmutzen, dass die wahre Wurzel des Giftes aber weiter östlich liegt, im {link:felwood}Teufelswald{/link}.]=],
		},
	},
})

Translate("deDE", "cliffspring-falls", {
	title = "Cliffspring Falls",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Cliffspring Falls stürzen aus den Bergen östlich von {link:auberdine}Auberdine{/link} herab. Der größte Teil der Gegend trinkt aus ihnen, und nun fließt ein Gift in ihrem Wasser und macht das Rotwild der {link:darkshore}Dunkelküste{/link} krank. Hinter den Fällen liegt eine Höhle, in der seltene Pilze wachsen. Die Uralten warnten die Bewohner von Auberdine, sich von ihr fernzuhalten, denn sie spürten, dass sich dort ein neues Übel eingenistet hatte. Sie hatten recht. Die {link:naga}Naga{/link} haben die Höhle eingenommen, und ein Nagafürst namens {link:lord-sinslayer}Sinslayer{/link} führt sie an.]=],
		},
	},
})

Translate("deDE", "blackwood-den", {
	title = "Bau der Schwarzfelle",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Bau der Schwarzfelle liegt im äußersten Süden der {link:darkshore}Dunkelküste{/link}, nahe der Grenze zum {link:ashenvale}Eschental{/link}. Er ist eine Ansammlung von Furbolglagern um eine kleine Höhle und gehört dem {link:blackwood-furbolgs}Stamm der Schwarzfelle{/link}. Ein {link:night-elves}Nachtelf{/link} namens {link:volcor}Volcor{/link} wurde hier von den {link:furbolgs}Furbolgs{/link} verwundet und suchte tief in der Höhle Zuflucht. Sein treuer Gefährte {link:grimclaw}Grimclaw{/link} ging allein nach Norden, um Hilfe zu holen. Der Bau ist ein finsteres Zeichen dafür, wie tief die Furbolgs gefallen sind. Einst lebten sie in Frieden mit den Elfen. Nun greifen sie jeden Elfen an, der sich ihren Feuern nähert.]=],
		},
	},
})

Translate("deDE", "remtravel-s-excavation", {
	title = "Remtravels Ausgrabung",
	aliases = { "Remtravels Grabung" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Remtravels Ausgrabung ist die Grabungsstätte der {link:explorers-league}Forscherliga{/link} im Südwesten der {link:darkshore}Dunkelküste{/link}. Hier legten {link:prospector-remtravel}Prospektor Remtravel{/link} und seine Leute Zeichen einer großen und uralten Gesellschaft frei. Dann wandte sich der Boden selbst gegen sie. Golems aus Stein erhoben sich aus der Erde und überrannten die Stätte, und die {link:troggs}Troggs{/link} der Gravelflint kamen mit ihnen. Die Grabungsmannschaft floh nach {link:auberdine}Auberdine{/link}. Der Prospektor nicht. Er ist noch immer irgendwo an der Grabung und sucht nach einem geheimnisvollen Fossil, das er schon einmal verloren hat. Was die Liga aus dem Fossil machen wird, kann in Auberdine niemand sagen.]=],
		},
	},
})

Translate("deDE", "the-master-s-glaive", {
	title = "Die Meistergleve",
	aliases = { "Meistergleve" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Meistergleve steht im Süden der {link:darkshore}Dunkelküste{/link}: eine gewaltige Klinge, in den Schädel eines gefallenen Riesen getrieben. {link:onu}Onu{/link} lehrt, dass einer der alten Herren der Erde hier in vergangenen Zeitaltern starb, von der Gleve durchbohrt. Der Herr ist lange tot, doch Splitter seiner Macht mögen in seinen Knochen verblieben sein. Der {link:twilight-s-hammer}Schattenhammer{/link} ist gekommen, um sie zu suchen. Seine Kultisten lagern unter der Klinge, und ihre Bücher enthalten Seiten uralter elfischer Magie, verdreht, um ihre alten Meister in die Welt zurückzurufen.]=],
		},
	},
})

Translate("deDE", "thundris-windweaver", {
	title = "Thundris Windweaver",
	subtitle = "Ältester von Auberdine",
	found = "Auberdine, im oberen Stockwerk des Rathauses",
	hint = [=[Sucht den Ältesten auf, der die täglichen Angelegenheiten von Auberdine lenkt.]=],
	allegiance = "Auberdine · Nachtelfen",
	aliases = { "Thundris" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Thundris Windweaver ist der Älteste von {link:auberdine}Auberdine{/link}. Er führt die täglichen Angelegenheiten der Stadt mit gerechter und ruhiger Hand. Er ist auch ihr eifrigster Erforscher der Verderbnis. Er hat diese Krankheit schon einmal gesehen, in lange vergangenen Zeiten, und er weiß, dass sie nicht an den Grenzen eines Waldes haltmacht.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Thundris sieht die ganze Gestalt der Not der {link:darkshore}Dunkelküste{/link}. Die Raserei der {link:furbolgs}Furbolgs{/link}, der verdorbene Fluss und die Werkzeuge der alten Hochgeborenen sind für ihn Teile eines einzigen Krieges. Er will auch, dass man {link:auberdine}Auberdine{/link} kennt. Die großen Städte erinnern sich nur daran, was die {link:great-sundering}Große Teilung{/link} den {link:night-elves}Nachtelfen{/link} nahm. Er möchte, dass sie sich an die Stadt erinnern, die noch steht.]=],
		},
		{
			title = "Taten",
			text = [=[• Er verfolgte die Vergiftung des {link:cliffspring-river}Cliffspring{/link} bis zum {link:felwood}Teufelswald{/link} zurück.
• Er erfuhr, dass die {link:satyrs}Satyrn{/link} die {link:blackwood-furbolgs}Furbolgs der Schwarzfelle{/link} durch Talismane verderben.
• Er lässt die magischen Relikte der Hochgeborenen von {link:ameth-aran}Ameth'Aran{/link} sammeln und zerstören.
• Er reinigt Kor-Edelsteine, die den {link:naga}Naga{/link} abgenommen wurden, für jene, die einen heiligen Pfad beschreiten.
• Er schrieb nach {link:stormwind-city}Stormwind{/link} und bat um Hilfe.]=],
		},
	},
	chapters = {
		{
			title = "Die verderbten Schwarzfelle",
			hint = "Lockt den Satyr hervor, der die nördlichen Furbolgs quält.",
			text = [=[Thundris mischte Mondbrunnenwasser unter die eigene Nahrung der {link:furbolgs}Furbolgs{/link} und ließ sie neben ihr Feuer stellen. Wer davon aß, war für einen Augenblick gereinigt. In diesem Augenblick kam der {link:satyrs}Satyr{/link}, der sie in seinem Bann hielt, heraus, um zu sehen, was schiefgegangen war. Sein Talisman wurde nach {link:auberdine}Auberdine{/link} gebracht. Thundris nannte es eine gewonnene Schlacht in einem langen Krieg.]=],
		},
		{
			title = "Werkzeuge der Hochgeborenen",
			hint = [=[Nehmt den Geistern von Ameth'Aran die Relikte der alten Hochgeborenen ab.]=],
			text = [=[Die Geister von {link:ameth-aran}Ameth'Aran{/link} tragen noch immer die Werkzeuge ihrer Magie. Thundris wünscht, sie wären in der Katastrophe untergegangen, die ihre Welt beendete. Da sie es nicht taten, wird er sie selbst zerstören.]=],
		},
		{
