Translate("deDE", "terenthis", {
	title = "Terenthis",
	subtitle = "Wächter über die Schwarzfelle",
	found = "Auberdine, nahe dem Posten der Schildwachen",
	hint = [=[Sprecht mit dem Nachtelfen in Auberdine, der den Zeichen der Verderbnis nachjagt.]=],
	allegiance = "Auberdine · Nachtelfen",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Terenthis ist ein {link:night-elves}Nachtelf{/link} aus {link:auberdine}Auberdine{/link}, der geschworen hat, die Verderbnis an ihrer Quelle zu finden. Einige seiner Verwandten wurden auf {link:teldrassil}Teldrassil{/link} vor einem verderbten {link:furbolgs}Furbolg{/link} gerettet. Seit jenem Tag hat er gelobt, dass niemand mehr aus seinem Volk auf gleiche Weise leiden soll, und er beobachtet die Furbolgs der {link:darkshore}Dunkelküste{/link} genau.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Terenthis war einer der Ersten, die zeigten, wie nahe die Gefahr gekommen war. Seine Späher fanden die Lager der {link:blackwood-furbolgs}Schwarzfelle{/link} verderbt, in Sichtweite von {link:auberdine}Auberdine{/link}. Er ist auch ein Freund derer, die allein in der Wildnis leben, und ein Freund in Not findet ihn bereit.]=],
		},
		{
			title = "Taten",
			text = [=[• Er schickte Späher aus, um ein verderbtes Furbolglager zu finden, und Kämpfer, um seine Reihen zu lichten.
• Er fertigte einen verzauberten Umhang aus Mondpirscherfellen, der seinen Träger für die Tiere der {link:darkshore}Dunkelküste{/link} unsichtbar machte.
• Er brachte {link:volcor}Volcor{/link} aus dem {link:blackwood-den}Bau der Schwarzfelle{/link} heim.
• Er sendet seine Erkenntnisse an den Ältesten, {link:thundris-windweaver}Thundris Windweaver{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Wie groß ist die Bedrohung?",
			hint = "Findet ein verderbtes Furbolglager nahe Auberdine.",
			text = [=[Das Lager südlich von {link:auberdine}Auberdine{/link} war schlimmer, als Terenthis befürchtet hatte. Die {link:blackwood-furbolgs}Schwarzfelle{/link} waren verderbt, und sie waren nah. Er sagte Auberdine, es solle sich auf das Kommende vorbereiten. Er sagte auch denen, die dort gekämpft hatten, sie sollten nicht trauern. Sie hatten die Bedrohung verringert, auch wenn das Teufelsmoos das Land noch immer vergiftete.]=],
		},
		{
			title = "Ein verlorener Meister",
			hint = "Folgt dem Ruf des Tieres, das allein nach Auberdine kam.",
			text = [=[{link:grimclaw}Grimclaw{/link} kam ohne seinen Meister nach {link:auberdine}Auberdine{/link}. Terenthis verstand sofort. {link:volcor}Volcor{/link} war verwundet, irgendwo im Süden unter den {link:furbolgs}Furbolgs{/link}. Er nähte einen Umhang, der seinen Träger vor den Tieren verbergen würde, und warnte, dass seine Magie versagen würde, wenn sein Träger mehr täte als zu sprechen.]=],
		},
	},
	mentions = {
		{ text = "Ein verlorener Meister" },
		{ text = "Flucht mit Gewalt" },
		{ text = "Flucht durch Heimlichkeit" },
		{ text = "{link:thundris-windweaver}Thundris Windweaver{/link}" },
		{
			text = [=[Reise ins {link:ashenvale}Eschental{/link}, ein Ruf von Schildwache Selarin]=],
		},
	},
	bonds = {
		{ id = "volcor", name = "Volcor", note = "sein Freund" },
		{ id = "grimclaw", name = "Grimclaw", note = "Volcors Gefährte" },
		{ id = "thundris-windweaver", name = "Thundris Windweaver", note = "der Älteste, dem er berichtet" },
		{ id = "blackwood-furbolgs", name = "Furbolgs der Schwarzfelle", note = "die Verderbnis, die er beobachtet" },
	},
})

Translate("deDE", "onu", {
	title = "Onu",
	subtitle = "Uralter des Wissens",
	found = "Der Hain der Uralten, im Süden der Dunkelküste",
	hint = [=[Sucht den Uralten des Wissens im Hain nahe den südlichen Bergen.]=],
	allegiance = "Die Uralten · Der Hain der Uralten",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Onu ist ein Uralter des Wissens, einer der großen Geister des Waldes, und er hütet den Hain der Uralten im Süden der {link:darkshore}Dunkelküste{/link}. Er spricht langsam und mit langen Pausen, und er eilt nicht. Er weiß, dass alle Dinge zu ihrer bestimmten Zeit geschehen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Onu ist das Gedächtnis der {link:darkshore}Dunkelküste{/link}. Er weiß, was die Kultisten des Schattenhammers verehren, und er weiß, wo einer ihrer alten Herren fiel. Die Druiden und Gelehrten von {link:auberdine}Auberdine{/link} richten ihre schwersten Fragen an ihn, und der Erzdruide {link:fandral-staghelm}Fandral Staghelm{/link} schickt ihm Botschaften aus {link:darnassus}Darnassus{/link}.]=],
		},
		{
			title = "Taten",
			text = [=[• Er schickte Beobachter zur {link:the-master-s-glaive}Meistergleve{/link} und erfuhr, dass der {link:twilight-s-hammer}Schattenhammer{/link} dort war.
• Er studierte eine Seite, die aus dem Folianten des Kults gerissen war, und spürte darin die Magie der Alten.
• Er sammelte Relikte aus {link:ruins-of-mathystra}Mathystra{/link}, um zu erfahren, wie der Kult elfische Magie nutzt.
• Er spricht von {link:malfurion-stormrage}Shan'do Stormrage{/link} als einem, der die Geduld des Waldes verstand.]=],
		},
	},
	chapters = {
		{
			title = "Die Meistergleve",
			hint = "Geht auf Bitten des Uralten zur Meistergleve.",
			text = [=[Onu fand es seltsam, dass die {link:naga}Naga{/link} an die {link:darkshore}Dunkelküste{/link} gekommen waren. Noch seltsamer fand er, dass der {link:twilight-s-hammer}Schattenhammer{/link} gekommen war. Als sich seine Befürchtungen bestätigten, sprach er von dem alten Herrn, der an der Gleve aufgespießt wurde. Dieser Herr ist tot. Seine Macht vielleicht nicht.]=],
		},
		{
			title = "Seiten der Alten",
			hint = [=[Bringt dem Uralten, was aus dem Lager des Kults genommen wurde.]=],
			text = [=[Die Kritzeleien, die aus dem Zwielichtfolianten gerissen worden waren, enthielten eine chaotische Magie, und darunter lag die Schrift von Elfen. Der Kult nutzte uralte elfische Zauberei, um seine alten Meister in die Welt zurückzubringen. Onu machte sich daran zu ergründen, wie, bevor seine Feinde vollenden konnten, was sie begonnen hatten.]=],
		},
		{
			title = "Die Treppe unter Mathystra",
			hint = [=[Bringt dem Uralten, was vom Wächter von Mathystra übrig blieb.]=],
			text = [=[Als die Kugel aus getrübtem Wasser vor ihn gelegt wurde, zeigte Onu etwas, das der Überraschung nahekam. Es gab eine Treppe unter {link:ruins-of-mathystra}Mathystra{/link}, und ein {link:the-night-watch}Wächter{/link} hatte über sie gewacht. Er sagte nur, dass er mit den anderen Uralten sprechen müsse und dass es gut sei, dass die Treppe gefunden wurde, bevor die {link:naga}Naga{/link} oder der Kult sie fanden.]=],
		},
	},
	mentions = {
		{
			text = [=[Onu, gerufen von {link:barithras-moonshade}Barithras Moonshade{/link}]=],
		},
		{ text = "Das Zwielichtlager" },
		{
			text = [=[{link:grove-of-the-ancients}Der Hain der Uralten{/link}, eine Botschaft von {link:fandral-staghelm}Fandral Staghelm{/link}]=],
		},
	},
	bonds = {
		{ id = "arbal", name = "Arbal", note = "steht mit ihm im Hain" },
		{ id = "barithras-moonshade", name = "Barithras Moonshade", note = "beherzigt seine Warnungen" },
		{ id = "fandral-staghelm", name = "Fandral Staghelm", note = "schickt ihm Kunde" },
		{ id = "baron-marinous", name = "Baron Marinous", note = "der Wächter von Mathystra" },
	},
})

