	},
	bonds = {
		{ id = "murkdeep", name = "Murkdeep", note = "der Murloc, den sie tot sehen wollte" },
		{ id = "jai-vhanel", name = "Jai'vhanel", note = "eine Wächterin, die dem Wahnsinn verfiel" },
	},
})

Translate("deDE", "tharnariun-treetender", {
	title = "Tharnariun Treetender",
	subtitle = "Heiler der Tiere",
	found = "Auberdine",
	hint = [=[Sprecht mit dem Nachtelfen, der ein Heilmittel für die kranken Bären des Waldes sucht.]=],
	allegiance = "Auberdine · Nachtelfen",
	aliases = { "Tharnariun" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Tharnariun Treetender hat versucht, die Seuche zu heilen, die die Distelbären der {link:darkshore}Dunkelküste{/link} befallen hat. Die einst edlen Tiere sind tollwütig geworden. Er baute eine Falle aus Licht, um sie zu beruhigen, in der Hoffnung, eines zu heilen. Das Heilmittel versagte. Nun muss er den Tod der Geschöpfe befehlen, die er retten wollte, und es bekümmert ihn.]=],
		},
		{
			title = "Taten",
			text = [=[• Er erprobte ein Heilmittel an einem gefangenen tollwütigen Bären.
• Er ließ die kranken Bären dezimieren, um die Seuche zu verlangsamen.
• Er befahl den Tod des Muttertiers, in einer Höhle nahe {link:bashal-aran}Bashal'Aran{/link}.
• Er warnte, dass viele Elfen lieber in sicherere Lande der {link:alliance}Allianz{/link} fliehen würden, als dem Leben in ihrer neuen Heimat ins Auge zu sehen.]=],
		},
	},
	mentions = {
		{ text = "Verseuchte Lande" },
		{ text = "Die Reinigung der Befallenen" },
		{ text = "Tharnariuns Hoffnung" },
	},
	bonds = {
		{ id = "alanndarian-nightsong", name = "Alanndarian Nightsong", note = "pflegt das kranke Rotwild" },
	},
})

Translate("deDE", "gwennyth-bly-leggonde", {
	title = "Gwennyth Bly'Leggonde",
	subtitle = "Gesandte des Tempels des Mondes",
	found = "Auberdine, nahe dem Hippogryphenhorst",
