Translate("deDE", "athrikus-narassin", {
	title = "Athrikus Narassin",
	subtitle = "Meister des Dunklen Strangs",
	found = "Die Spitze des Turms von Althalaxx",
	hint = [=[Stellt Euch dem uralten Hexenmeister, der an der Spitze des Turms von Althalaxx wartet.]=],
	allegiance = "Kult des Dunklen Strangs · einst die Hochgeborenen",
	aliases = { "Athrikus" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Athrikus Narassin war ein Fürst der Hochgeborenen und ein bevorzugter Diener von {link:queen-azshara}Königin Azshara{/link}. Sie übertrug ihm die Herrschaft über die Zwillingsstädte {link:ameth-aran}Ameth'Aran{/link} und {link:bashal-aran}Bashal'Aran{/link}, doch er blieb in seinem Turm. Als die Welt zerbrach, versprach er den Bewohnern von Ameth'Aran durch einen Zauber ewiges Leben. Ihre Geister verweilen noch immer in den Ruinen. Er band auch seinen eigenen Stellvertreter, {link:asterion}Asterion{/link}, in einem Gefängnis aus Stein und Magie. Athrikus lebt, und er führt den {link:cult-of-the-dark-strand}Kult des Dunklen Strangs{/link}.]=],
		},
		{
			title = "Taten",
			text = [=[• Er regierte die Zwillingsstädte für {link:azshara}Azshara{/link}.
• Er band Seelen von Hochgeborenen in Seelensteine und schöpfte seine Macht aus ihnen.
• Er versammelte eine Schar von Hexenmeistern in seinem alten Turm.]=],
		},
	},
	mentions = {
		{ text = "Der {link:tower-of-althalaxx}Turm von Althalaxx{/link}" },
		{ text = "Der {link:tower-of-althalaxx}Turm von Althalaxx{/link}" },
	},
	bonds = {
		{ id = "asterion", name = "Asterion", note = "der Diener, den er einkerkerte" },
		{ id = "balthule-shadowstrike", name = "Balthule Shadowstrike", note = "Feind" },
	},
})

Translate("deDE", "asterion", {
	title = "Asterion",
	subtitle = "Der Gefangene von Bashal'Aran",
	found = "Ein Schrein auf einer Klippe im Westen von Bashal'Aran",
	hint = [=[Sucht die Quelle des blauen Lichts in den Ruinen von Bashal'Aran.]=],
	allegiance = "einst die Hochgeborenen",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Asterion war ein Magier der Hochgeborenen, in den Zwillingsstädten nur {link:athrikus-narassin}Athrikus Narassin{/link} untergeordnet, und berühmt für die Stärke seines Arms ebenso wie seiner Zauber. Als er zuletzt frei wandelte, stand der {link:well-of-eternity}Brunnen der Ewigkeit{/link} noch. Sein Meister versiegelte ihn mit einem Uralten Mondsteinsiegel in einem Schrein bei {link:bashal-aran}Bashal'Aran{/link}, und mehr als tausend Jahre lang starrte er auf dessen Säulen. Seine Zunge ist scharf. Er fürchtet, dass seine lange Einsamkeit seinen Verstand gebrochen hat.]=],
		},
	},
	chapters = {
		{
			title = "Das zerstörte Siegel",
			hint = [=[Befreit den Geist, der im Schrein von Bashal'Aran gefangen ist.]=],
			text = [=[Das Siegel wurde den {link:satyrs}Satyrn{/link} abgenommen und in der blauen Flamme von {link:ameth-aran}Ameth'Aran{/link} zerstört. Asterion war frei. Er spürte, dass sein alter Meister noch lebte, und seine Verzweiflung wandte sich der Rache zu.]=],
		},
	},
	mentions = {
		{ text = "{link:bashal-aran}Bashal'Aran{/link}" },
		{ text = "{link:bashal-aran}Bashal'Aran{/link}" },
	},
	bonds = {
		{ id = "athrikus-narassin", name = "Athrikus Narassin", note = "sein früherer Meister und Kerkermeister" },
	},
})

Translate("deDE", "anaya-dawnrunner", {
	title = "Anaya Dawnrunner",
	subtitle = "Die Heimgesuchte von Ameth'Aran",
	found = "Die Ruinen von Ameth'Aran",
	hint = [=[Stellt Euch dem ruhelosen Geist, der die Ruinen von Ameth'Aran heimsucht.]=],
	allegiance = "einst das Volk von Ameth'Aran",
	aliases = { "Anaya" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Anaya Dawnrunner lebte in {link:ameth-aran}Ameth'Aran{/link}, als der Krieg am {link:well-of-eternity}Brunnen der Ewigkeit{/link} die Welt zerriss. Sie war die Geliebte von {link:cerellean-whiteclaw}Cerellean Whiteclaw{/link}. Als die Stadt fiel, hielt er sie für tot. Zehntausend Jahre später fand er ihren Geist in den Ruinen umherwandelnd, dort gebunden wie die anderen, die dem Versprechen von {link:athrikus-narassin}Athrikus{/link} vertrauten.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Ihre Geschichte ist der Kummer von {link:ameth-aran}Ameth'Aran{/link}, klein genug gemacht, um ihn in den Händen zu halten. Ihr Geist konnte nur befreit werden, indem er zerstört wurde, und der, der sie liebte, brachte es nicht über sich.]=],
		},
	},
	mentions = {
		{ text = "Für die ewige Liebe" },
	},
	bonds = {
		{ id = "cerellean-whiteclaw", name = "Cerellean Whiteclaw", note = "ihr Geliebter" },
	},
})

Translate("deDE", "cerellean-whiteclaw", {
	title = "Cerellean Whiteclaw",
	subtitle = "Ein erwachter Schläfer",
	found = "Auberdine",
	hint = [=[Sprecht mit dem trauernden Nachtelfen in Auberdine, der von Ameth'Aran träumt.]=],
	allegiance = "Auberdine · Nachtelfen",
	aliases = { "Cerellean" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Cerellean Whiteclaw hörte nach den Schlachten am {link:well-of-eternity}Brunnen der Ewigkeit{/link}, dass {link:ameth-aran}Ameth'Aran{/link} zerstört worden sei und mit ihm seine Liebste {link:anaya-dawnrunner}Anaya{/link}. Er folgte {link:malfurion-stormrage}Shan'do Stormrage{/link} in den langen Schlaf und trug seinen Kummer in seine Träume. Nun ist er erwacht, und die Erinnerung an sie verfolgt ihn noch immer. Als er durch die Wälder streifte, fand er ihren Geist in den Ruinen.]=],
		},
	},
	chapters = {
		{
			title = "Für die ewige Liebe",
			hint = "Befreit den Geist von Anaya Dawnrunner.",
			text = [=[Cerellean wusste, dass ihr Geist erlöst werden musste, und er wusste, dass er es nicht tun konnte. Als ihm ihr Anhänger zurückgebracht wurde, fragte er sich, ob er die Kraft nicht selbst hätte finden sollen. Dann bat er darum, allein gelassen zu werden.]=],
		},
	},
	bonds = {
		{ id = "anaya-dawnrunner", name = "Anaya Dawnrunner", note = "seine Geliebte" },
	},
})

