		{
			title = "Zusammenfassung",
			text = [=[Arbal ist ein Uralter des Krieges, der neben {link:onu}Onu{/link} im Hain der Uralten steht. Wo Onu zur Geduld rät, rät Arbal zum Krieg. Er nennt die {link:naga}Naga{/link} verfluchte Hochgeborene, gefallen von dem, was sie einst waren. Sie plündern nun ihre eigene alte Heimat in {link:ruins-of-mathystra}Mathystra{/link} und helfen vielleicht dem {link:twilight-s-hammer}Schattenhammer{/link}. Arbal vergibt ihnen nicht.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Die Uralten des Krieges kämpften in den großen Schlachten ihrer Geschichte an der Seite der {link:night-elves}Nachtelfen{/link}. Dass nun einer an der {link:darkshore}Dunkelküste{/link} steht, zeigt, wie schwer der Hain die Gefahr im Norden gewichtet.]=],
		},
		{
			title = "Taten",
			text = [=[• Er schickt Kämpfer gegen die {link:naga}Naga{/link} der Stormscale in {link:ruins-of-mathystra}Mathystra{/link}.]=],
		},
	},
	mentions = {
		{ text = "Wachsende Streitkräfte" },
	},
	bonds = {
		{ id = "onu", name = "Onu", note = "steht mit ihm im Hain" },
	},
})

Translate("deDE", "baron-marinous", {
	title = "Baron Marinous",
	subtitle = "Wächter von Mathystra",
	found = "Die Ruinen von Mathystra",
	hint = [=[Stellt Euch dem Elementar, das einen verborgenen Weg in den Ruinen von Mathystra bewacht.]=],
	allegiance = "Unbekannt",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Baron Marinous ist ein mächtiges Elementar, das eine Treppe bewacht, die unter die Ruinen von {link:ruins-of-mathystra}Mathystra{/link} hinabführt. Wenn es bezwungen ist, bleibt nur eine Kugel aus Wasser zurück, von innen getrübt durch etwas, das sich nicht sehen lassen will. Was es bewachte und wer es dort hinstellte, weiß noch niemand.]=],
		},
		{
			title = "Unaufgezeichnet",
			text = [=[Nirgends steht geschrieben, wem {link:the-baron}der Baron{/link} dient. {link:onu}Onu{/link} ist gegangen, um mit den anderen Uralten zu sprechen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Die Anwesenheit des Barons beweist, dass {link:ruins-of-mathystra}Mathystra{/link} mehr verbirgt als zerbrochene Steine. Etwas unter den Ruinen galt als bewachenswert, und es ist auf irgendeine Weise noch immer wirksam.]=],
		},
	},
	mentions = {
		{ text = "Baron Marinous" },
	},
	bonds = {
		{ id = "onu", name = "Onu", note = "erforscht seine Überreste" },
	},
})

Translate("deDE", "jai-vhanel", {
	title = "Jai'vhanel",
	subtitle = "Die schwarze Eule",
	found = "Nördlich von Ameth'Aran, nahe dem Fuß der Berge",
	hint = [=[Stellt Euch der schwarzen Eule, die nördlich von Ameth'Aran jagt.]=],
	allegiance = "Die Wildnis",
	aliases = { "Schwertfeder" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Jai'vhanel, genannt Schwertfeder, ist eine große Eule mit Federn schwarz wie Gagat. Lange Zeit war sie eine Wächterin des Landes rund um {link:ameth-aran}Ameth'Aran{/link}. Dann verfiel sie dem Wahnsinn und begann, Reisende auf der Straße nach {link:auberdine}Auberdine{/link} anzugreifen. Niemand weiß, was sie dazu trieb. Die {link:sentinels}Schildwachen{/link} setzten ein Kopfgeld auf sie aus.]=],
		},
		{ title = "Unaufgezeichnet", text = "Die Ursache ihres Wahnsinns ist unbekannt." },
		{
			title = "Bedeutung",
			text = [=[Die {link:sentinels}Schildwachen{/link} jagten sie nicht gern. Ihr Fall ist ein weiteres Zeichen, dass mit den Geschöpfen der {link:darkshore}Dunkelküste{/link} etwas nicht stimmt, von den Bären des Waldes bis zu den Vögeln der Hügel.]=],
		},
	},
	mentions = {
		{ text = "GESUCHT: Jai'vhanel" },
	},
	bonds = {
		{ id = "sentinel-glynda-nal-shea", name = "Schildwache Glynda Nal'Shea", note = "setzte das Kopfgeld aus" },
	},
})

Translate("deDE", "lord-sinslayer", {
	title = "Lord Sinslayer",
	subtitle = "Naga der Cliffspring Falls",
	found = "Die Höhle hinter den Cliffspring Falls",
	hint = [=[Stellt Euch dem Nagafürsten, der in der Höhle hinter den Cliffspring Falls lauert.]=],
	allegiance = "Naga",
	aliases = { "Sinslayer" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Lord Sinslayer führt die {link:naga}Naga{/link} an, die die Höhle hinter den {link:cliffspring-falls}Cliffspring Falls{/link} eingenommen haben. Die Uralten spürten das Übel in dieser Höhle, bevor irgendein Elf es gesehen hatte. Die Fälle liefern der {link:darkshore}Dunkelküste{/link} einen Großteil ihres Trinkwassers, und das Gift, das nun aus ihnen fließt, hat das Rotwild im ganzen Land krank gemacht.]=],
		},
		{
			title = "Unaufgezeichnet",
			text = [=[Über Sinslayer ist wenig bekannt außer seinem Namen und seinem Unterschlupf.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Sinslayers Höhle liegt näher an {link:auberdine}Auberdine{/link} als {link:ruins-of-mathystra}Mathystra{/link}. Seine Anwesenheit zeigt, dass sich die {link:naga}Naga{/link} nicht länger mit den alten Ruinen des Nordostens begnügen.]=],
		},
	},
	bonds = {
		{ id = "barithras-moonshade", name = "Barithras Moonshade", note = "wurde vor seiner Höhle gewarnt" },
	},
})

Translate("deDE", "murkdeep", {
	title = "Murkdeep",
	subtitle = "Schrecken der Greymist",
	found = "Ein Murloclager an der Küste südlich von Auberdine",
	hint = [=[Stellt Euch dem Murloc, der die Hütten an der südlichen Küste bewacht.]=],
	allegiance = "Murlocs der Greymist",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Murkdeep ist ein {link:murlocs}Murloc{/link} vom Stamm der Greymist, der ein Hüttenlager an der Küste südlich von {link:auberdine}Auberdine{/link} bewacht. Er hat mindestens eine Schildwache getötet. Man glaubt auch, dass er zwei Frachtschiffe vor der Küste versenkt hat. Der Dorfrat hat ein Kopfgeld auf ihn ausgesetzt, und die Stadtbewohner sagen, sie würden ruhiger schlafen, wenn es ausgezahlt ist.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Murkdeep ist der Grund, warum die Fischer von {link:auberdine}Auberdine{/link} ihre Boote an Land lassen, und der Grund, warum Fracht vom Meer spät oder gar nicht ankommt.]=],
		},
	},
	mentions = {
		{ text = "GESUCHT: Murkdeep!" },
	},
	bonds = {
		{ id = "sentinel-glynda-nal-shea", name = "Schildwache Glynda Nal'Shea", note = "zahlt das Kopfgeld aus" },
	},
})

Translate("deDE", "kerlonian-evershade", {
	title = "Kerlonian Evershade",
	subtitle = "Druide der Klaue",
	found = "Nahe dem Hain der Uralten",
	hint = [=[Findet den schläfrigen Druiden, der nahe dem südlichen Hain seine Sachen verloren hat.]=],
	allegiance = "Druiden der Klaue",
	aliases = { "Kerlonian" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Kerlonian Evershade ist ein Druide der Klaue, der kürzlich aus dem {link:emerald-dream}Smaragdgrünen Traum{/link} erwacht ist. Seitdem ist er schläfrig. Er machte sich auf den Weg zu {link:maestra-s-post}Maestras Posten{/link}, um {link:liladris-moonriver}Liladris Moonriver{/link} zu treffen, hielt für ein kurzes Nickerchen an und verlor seine Habseligkeiten. Ein Horn in seiner Truhe wird ihn wecken, falls er wieder einnickt.]=],
		},
		{
			title = "Taten",
			text = [=[• Er erwachte aus dem Smaragdgrünen Traum und nahm die Straße nach Süden in Richtung {link:ashenvale}Eschental{/link}.
• Unterwegs schlief er wieder ein und braucht einen Führer, um {link:maestra-s-post}Maestras Posten{/link} zu erreichen.]=],
		},
	},
	mentions = {
		{ text = "Der Schläfer ist erwacht" },
	},
	bonds = {
		{ id = "cerellean-whiteclaw", name = "Cerellean Whiteclaw", note = "ein weiterer erwachter Schläfer" },
	},
})

Translate("deDE", "cult-of-the-dark-strand", {
	title = "Kult des Dunklen Strangs",
	aliases = { "Dunkler Strang" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Kult des Dunklen Strangs ist eine Schar von Hexenmeistern, die den {link:tower-of-althalaxx}Turm von Althalaxx{/link} an der {link:darkshore}Dunkelküste{/link} eingenommen hat. Er hatte keinen Namen, den die {link:sentinels}Schildwachen{/link} kannten, bis {link:balthule-shadowstrike}Balthule Shadowstrike{/link} einen aus Fetzen seines Pergaments zusammensetzte. Seine Fanatiker und Leerenrufer dienen {link:athrikus-narassin}Athrikus Narassin{/link}, dem uralten Fürsten der Hochgeborenen, dem der Turm gehört.]=],
		},
		{
			title = "Seine Macht",
			text = [=[Der Kult schöpft aus Seelensteinen. {link:athrikus-narassin}Athrikus{/link} hielt die Seelen von Hochgeborenen in ihnen gefangen und verbarg sie in den Landen der {link:satyrs}Satyrn{/link} im nördlichen {link:ashenvale}Eschental{/link}, bei {link:night-run}Night Run{/link} und {link:satyrnaar}Satyrnaar{/link}. Der Kult ist auch in {link:the-ruins-of-ordil-aran}Ordil'Aran{/link} im Eschental tätig. Er steht in Verbindung mit dem orcischen Hexenmeister {link:ilkrud-magthrull}Ilkrud Magthrull{/link} vom {link:fire-scar-shrine}Fire Scar-Schrein{/link}, der Aufzeichnungen über seine Pläne führte. {link:delgren-the-purifier}Delgren der Läuterer{/link} hat es sich zur Aufgabe gemacht, ihm ein Ende zu setzen.]=],
		},
	},
})

Translate("deDE", "blackwood-furbolgs", {
	title = "Furbolgs der Schwarzfelle",
	aliases = { "Schwarzfelle", "Stamm der Schwarzfelle" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Schwarzfelle sind ein Stamm der {link:furbolgs}Furbolgs{/link} an der {link:darkshore}Dunkelküste{/link}. Sie waren Freunde der {link:night-elves}Nachtelfen{/link}, und die Elfen erinnern sich noch immer so an sie. Nun sind sie verderbt. Sie leben in {link:camping}Lagern{/link} entlang des {link:cliffspring-river}Cliffspring{/link} im Norden und im Süden, und sie greifen jeden Elfen an, der ihnen nahe kommt.]=],
		},
		{
			title = "Die Verderbnis",
			text = [=[Die Elfen von {link:auberdine}Auberdine{/link} haben einen Teil des Wahnsinns der Schwarzfelle auf die {link:satyrs}Satyrn{/link} zurückgeführt. Ein Satyrverderber hält sie durch einen Talisman in seiner Gewalt. Als die {link:furbolgs}Furbolgs{/link} Nahrung aßen, die mit Mondbrunnenwasser vermischt war, wurden sie für kurze Zeit gereinigt. Der Älteste von Auberdine hofft, dass sie eines Tages für immer befreit werden können. Doch das tiefere Gift fließt im Land und im Wasser, und es kommt aus dem {link:felwood}Teufelswald{/link}.]=],
		},
	},
})
